/* Minimal botanical palette inspired by the supplied leaf reference. */
:root{--navy:#fff;--blue:#16885b;--pale:#e9f7ee;--ink:#172d24;--muted:#76847c;--line:#e5ede7;--bg:#f6f9f6;--green:#16885b;--amber:#9a7130;--shadow:0 8px 28px rgba(25,75,48,.055)}
body{font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","Segoe UI",sans-serif;background:var(--bg);color:var(--ink)}
.sidebar{background:#fff;color:var(--ink);border-right:1px solid var(--line)}
.brand b,.entry-brand b{color:#17382a;letter-spacing:-.35px}
.brand small,.entry-brand small{color:#87958b}
.label{color:#84938a}
.nav button{color:#5c6e62}
.nav button.active,.nav button:hover{background:#edf7f0;color:#176c47}
.nav button.active{box-shadow:inset 3px 0 #36ae70}
.demobadge{border-color:#e4eee7;color:#738278;background:#f8fbf8}
.demobadge i{background:#48bf7c}
.user{border-color:var(--line)}
.user small{color:#87958b}
.avatar{background:#e6f5eb;color:#17764d}
.top{background:rgba(255,255,255,.92);backdrop-filter:blur(16px);border-color:var(--line)}
.env{color:#16744b;background:#eaf7ef}
.heading h1,.entry-card h1,.entry-wide h1{font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display","Segoe UI",sans-serif;color:#183c2b;letter-spacing:-.65px}
.eyebrow{color:#198454}
.btn,.select,.search{border-radius:11px;color:#40574a}
.btn.primary{background:#16885b;border-color:#16885b}
.btn.primary:hover{background:#11764d}
.card{border-color:var(--line);box-shadow:var(--shadow);border-radius:17px}
.kpi i,.module-icon{background:#eaf7ef;color:#16885b}
.positive,.status{color:#16764d}
.tabs{border-color:var(--line)}
.tab.active{color:#16885b;border-color:#38b875}
.subtab.active{background:#e8f6ed;color:#15784f;border-color:#cfe9d9}
th{background:#f1f7f2;color:#596e60}
td{border-color:#edf2ee;color:#43584a}
tbody tr:hover{background:#f7faf7}
.fill{background:linear-gradient(90deg,#16885b,#86d4a7)}
.account-item{color:#365344}
.account-item:hover{background:#f3f8f4}
.entry-screen{background:radial-gradient(ellipse at 84% 12%,#e4f5ea 0,transparent 33%),linear-gradient(150deg,#f5faf6,#fbfcfb 62%,#eef7f0)}
.entry-card{border-color:#e7eee8;box-shadow:0 24px 64px rgba(28,72,47,.09);border-radius:22px}
.login-field label{color:#55695c}
.login-field input{border-radius:11px;border-color:#e3ebe5}
.login-field input:focus{border-color:#69bd8b;box-shadow:0 0 0 3px rgba(53,177,111,.13)}
.demo-hint{background:#f1f8f3;color:#718076;border-radius:11px}
.module-card{border-color:#e5ede7;border-radius:19px;box-shadow:0 8px 28px rgba(25,75,48,.05)}
.module-card:hover{border-color:#afd9bd;box-shadow:0 17px 38px rgba(25,75,48,.09)}
.module-card h2{font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display","Segoe UI",sans-serif;color:#183c2b;letter-spacing:-.25px}
.module-open{color:#16885b}
.entry-top .user-chip{color:#47745a;border-color:#e1eee5;background:#fff}
.modalfoot{background:#f8fbf8}
.modalbg{background:rgba(21,43,29,.34);backdrop-filter:blur(5px)}
.mark{position:relative;overflow:hidden;background:linear-gradient(145deg,#e1f5e9,#f3fbf5);color:transparent!important;border:1px solid #d8eee0;border-radius:12px;font-size:0!important;box-shadow:inset 0 0 0 1px rgba(255,255,255,.55)}
.mark:before,.mark:after{content:"";position:absolute;width:12px;height:25px;top:5px;border-radius:100% 0 100% 0;transform:rotate(-37deg)}
.mark:before{left:7px;background:linear-gradient(180deg,#91dfb1,#31b678);opacity:.92}
.mark:after{right:6px;top:4px;height:27px;background:linear-gradient(180deg,#b4e8c8,#56c58b);transform:rotate(37deg);opacity:.9}
@media(max-width:720px){.sidebar{box-shadow:14px 0 34px rgba(24,55,35,.12)}}

/* Keep the content canvas inside the space beside the fixed sidebar. */
html,body{width:100%;max-width:100%;overflow-x:hidden}
.main{width:calc(100% - 238px);min-width:0;margin-left:238px;overflow-x:clip}
.content{width:100%;max-width:100%;min-width:0;margin:0 auto}
.page,.grid,.heading,.heading>div,.tablebar,.tablebar>.row{min-width:0}
.summary{grid-template-columns:repeat(4,minmax(0,1fr))}
.tablewrap{width:100%;max-width:100%;min-width:0;overflow:auto}
@media(max-width:1000px){.sidebar{width:215px}.main{width:calc(100% - 215px);margin-left:215px}.summary{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:720px){.main{width:100%;margin:0;overflow-x:clip}.content{padding:20px 14px 40px}.summary{grid-template-columns:repeat(2,minmax(0,1fr))}.heading>div{width:100%}}
