function lineChart(vals,labels){let w=700,h=190,l=38,r=5,t=10,bot=24,max=Math.max(...vals)*1.2,pts=vals.map((v,i)=>[l+i*(w-l-r)/(vals.length-1),t+(h-t-bot)*(1-v/max)]);let path=pts.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');document.querySelector('#lineHolder').innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><defs><linearGradient id="g" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#16885b" stop-opacity=".2"/><stop offset="1" stop-color="#16885b" stop-opacity="0"/></linearGradient></defs>${[0,.33,.66,1].map(f=>`<line x1="${l}" x2="${w-r}" y1="${t+f*(h-t-bot)}" y2="${t+f*(h-t-bot)}" stroke="#edf1f5"/>`).join('')}<path d="${path} L ${pts.at(-1)[0]} ${h-bot} L ${l} ${h-bot} Z" fill="url(#g)"/><path d="${path}" fill="none" stroke="#16885b" stroke-width="2.5"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="white" stroke="#16885b" stroke-width="2" onmouseover="this.setAttribute('r',7)" onmouseout="this.setAttribute('r',5)"/><text x="${p[0]}" y="${h-4}" text-anchor="middle" fill="#8794a5" font-size="9">${labels[i]}</text>`).join('')}</svg>`}function donut(el,vals,labels,colors){let total=vals.reduce((a,b)=>a+b,0),r=62,c=2*Math.PI*r,offset=0;let seg=vals.map((v,i)=>{let d=c*v/total,s=`<circle cx="91" cy="83" r="${r}" fill="none" stroke="${colors[i]}" stroke-width="18" stroke-dasharray="${d} ${c-d}" stroke-dashoffset="${-offset}" transform="rotate(-90 91 83)"/>`;offset+=d;return s}).join('');document.querySelector(el).innerHTML=`<svg viewBox="0 0 310 170"><circle cx="91" cy="83" r="62" fill="none" stroke="#edf5ef" stroke-width="18"/>${seg}<text x="91" y="80" text-anchor="middle" font-size="20" font-family="Manrope" font-weight="800" fill="#19314f">${fmt(total)}</text><text x="91" y="96" text-anchor="middle" font-size="9" fill="#8996a7">TOTAL</text>${labels.map((x,i)=>`<circle cx="190" cy="${38+i*26}" r="4" fill="${colors[i]}"/><text x="202" y="${41+i*26}" font-size="10" fill="#62738a">${x}</text>`).join('')}</svg>`}function renderDash()