function csv(name,rows){let txt='\ufeff'+rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([txt],{type:'text/csv;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('Archivo CSV descargado')}
let creditTab='Distribuidor';function renderCredits(){let q=document.querySelector('#creditSearch').value.toLowerCase(),st=document.querySelector('#creditStatus').value,sv=document.querySelector('#creditState').value;let rows=credits.filter(r=>(!q||r.join(' ').toLowerCase().includes(q))&&(!st||r[11]===st)&&(!sv||r[7]===sv)&&(creditTab==='Aprobadas'?r[11]==='Aprobado':creditTab==='Completadas'?r[11]==='Completada':true));document.querySelector('#creditTable tbody').innerHTML=rows.map(r=>`<tr>${r.slice(0,11).map((v,i)=>`<td>${i===0?'<b>'+v+'</b>':esc(v)}</td>`).join('')}<td>${status(r[11])}</td></tr>`).join('')||'<tr><td colspan="12">Sin resultados para estos filtros.</td></tr>';document.querySelector('#creditFoot').textContent=`Mostrando ${rows.length} filas de ejemplo`}['creditSearch','creditStatus','creditState'].forEach(id=>document.querySelector('#'+id).addEventListener(id==='creditSearch'?'input':'change',renderCredits));renderCredits();document.querySelectorAll('#creditTabs .tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('#creditTabs .tab').forEach(x=>x.classList.toggle('active',x===b));creditTab=b.textContent;document.querySelector('#creditCount').textContent=creditTab==='Aprobadas'?'72':creditTab==='Completadas'?'94':'1,636';renderCredits();notify('Vista: '+creditTab)});document.querySelectorAll('#types .subtab').forEach(b=>b.onclick=()=>{document.querySelectorAll('#types .subtab').forEach(x=>x.classList.toggle('active',x===b));notify('Tipo de nota: '+b.textContent)});document.querySelector('#exportCredit').onclick=()=>csv('notas-de-credito-demo.csv',[['Folio','Fecha','Distribuidor','Unidades','EAN','CP','Ciudad','Estado','Segmento','Cliente','Estatus'],...credits]);
function monthly(rows){return `<div class="tablewrap"><table><thead><tr><th>Nombre</th>${months.map(m=>`<th>${m}</th>`).join('')}<th>Total</th></tr></thead><tbody>${rows.map(([n,a])=>`<tr><td><b>${esc(n)}</b></td>${a.map(v=>`<td>${v}</td>`).join('')}<td><b>${fmt(a.reduce((x,y)=>x+y,0))}</b></td></tr>`).join('')}</tbody></table></div>`}let moveNames=['Desplazamientos','Distribuidores','Médicos prescriptores','Centros oncológicos','Dist. por estado','Adherencia'];function renderMove(n=moveNames[0]){document.querySelectorAll('#moveTabs .tab').forEach(b=>b.classList.toggle('active',b.textContent===n));let q=document.querySelector('#moveSearch').value.toLowerCase(),host=document.querySelector('#moveTable');document.querySelector('#moveTitle').textContent=n==='Desplazamientos'?'Desplazamiento distribuidores · Totales 2,364':n;let html='';if(n==='Desplazamientos'||n==='Distribuidores')html=monthly(distributions.filter(r=>r[0].toLowerCase().includes(q)));else if(n==='Médicos prescriptores')html=monthly(prescribers.filter(r=>r[0].toLowerCase().includes(q)));else if(n==='Centros oncológicos')html=monthly(oncology.filter(r=>r[0].toLowerCase().includes(q)));else if(n==='Dist. por estado')html=`<div class="tablewrap"><table><thead><tr><th>Nombre</th><th>Clínica</th><th>Hospital</th><th>Subdistribuidores</th><th>Sin esquema</th><th>Total</th></tr></thead><tbody>${stateRows.filter(r=>r[0].toLowerCase().includes(q)).map(r=>`<tr><td><b>${r[0]}</b></td>${r.slice(1).map(x=>`<td>${fmt(x)}</td>`).join('')}<td><b>${fmt(r.slice(1).reduce((x,y)=>x+y,0))}</b></td></tr>`).join('')}</tbody></table></div>`;else html=`<div class="tablewrap"><table class="adhtable"><thead><tr><th>Caso</th><th>Estatus</th><th>Meses</th><th>Activación</th>${months.map(m=>`<th>${m}</th>`).join('')}</tr></thead><tbody>${adherence.filter(r=>r[0].toLowerCase().includes(q)).map(r=>`<tr><td><b>${r[0]}</b></td><td>${status(r[1])}</td><td>${r[2]}</td><td>${r[3]}</td>${r[4].map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;host.innerHTML=html}document.querySelectorAll('#moveTabs .tab').forEach(b=>b.onclick=()=>renderMove(b.textContent));document.querySelector('#moveSearch').oninput=()=>renderMove(document.querySelector('#moveTabs .tab.active').textContent);renderMove();document.querySelector('#exportMov').onclick=()=>csv('desplazamientos-demo.csv',[['Distribuidor',...months,'Total'],...distributions.map(([n,a])=>[n,...a,a.reduce((x,y)=>x+y,0)])]);
function renderCenters(){let q=document.querySelector('#centerSearch').value.toLowerCase(),st=document.querySelector('#centerStatus').value,pl=document.querySelector('#centerPlan').value,rows=centers.filter(r=>(!q||r.join(' ').toLowerCase().includes(q))&&(!st||r[6]===st)&&(!pl||r[7]===pl));document.querySelector('#centerTable tbody').innerHTML=rows.map(r=>`<tr><td><b>${esc(r[0])}</b></td><td>${esc(r[1])}</td><td>${esc(r[2])}</td>${r.slice(3,6).map(x=>`<td><button class="link" onclick="notify('${esc(r[1])} · Documento de demostración')">${x}</button></td>`).join('')}<td>${status(r[6])}</td><td>${esc(r[7])}</td><td><button class="link" onclick="notify('Opciones del centro')">•••</button></td></tr>`).join('')||'<tr><td colspan="9">No encontramos centros.</td></tr>';document.querySelector('#centerTotal').textContent=128+Math.max(0,centers.length-9)}document.querySelector('#centerSearch').oninput=renderCenters;document.querySelector('#centerStatus').onchange=renderCenters;document.querySelector('#centerPlan').onchange=renderCenters;renderCenters();document.querySelector('#exportCenters').onclick=()=>csv('centros-autorizados-demo.csv',[['RFC','Nombre','Contacto','Permiso','Constancia fiscal','Acuerdo','Estatus','Plan'],...centers]);
const modal=document.querySelector('#modal');document.querySelector('#newCenter').onclick=()=>modal.classList.add('open');document.querySelector('#close').onclick=document.querySelector('#cancel').onclick=()=>modal.classList.remove('open');modal.onclick=e=>{if(e.target===modal)modal.classList.remove('open')};document.querySelector('#centerForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);centers.unshift([String(f.get('rfc')).toUpperCase(),f.get('name'),f.get('email'),f.get('permit').name?'Ver':'Cargar',f.get('fiscal').name?'Ver':'Cargar',f.get('agreement').name?'Ver':'Cargar','Pendiente de registro',f.get('plan')]);renderCenters();modal.classList.remove('open');e.target.reset();notify('Centro registrado en esta sesión')};document.querySelector('#exportDash').onclick=()=>csv('resumen-comercial-demo.csv',[['Indicador','Valor'],['Desplazamientos',2364],['Notas de crédito',184],['Centros autorizados',128],['Ventas distribuidores',18600000]]);

</script></body></html>
